// Rebuilds assets/manifest.js from the image files in assets/.
// Run with: node tools/art-manifest.js
// A file's name is its art name: assets/sky.portside.jpg -> "sky.portside".
const fs = require('fs');
const path = require('path');
const dir = path.join(__dirname, '..', 'assets');
const files = {};
for (const f of fs.readdirSync(dir).sort()) {
  const m = f.match(/^(.+)\.(jpg|jpeg|png|webp)$/i);
  if (m) files[m[1]] = 'assets/' + f;
}
const out = '/* Generated by tools/art-manifest.js — the painted art that\'s in the repo.\n' +
  '   Do not edit by hand: add or remove files in assets/ and run the tool. */\n' +
  'window.DR = window.DR || {};\nwindow.DR.ArtManifest = { files: ' + JSON.stringify(files, null, 2) + ' };\n';
fs.writeFileSync(path.join(dir, 'manifest.js'), out);
console.log(Object.keys(files).length + ' pictures listed');
